import{_ as t}from"./chunks/calendar-plus.DIshg-3Q.js";import{_ as s,o as r,c as n,a3 as a}from"./chunks/framework.BlfGB29P.js";const f=JSON.parse('{"title":"Calendar +","description":"Ensemble de widgets de calendrier dédié, incluant la détection automatique des calendriers, une liste des événements et une fenêtre contextuelle (pop-up) pour les détails.","frontmatter":{"title":"Calendar +","description":"Ensemble de widgets de calendrier dédié, incluant la détection automatique des calendriers, une liste des événements et une fenêtre contextuelle (pop-up) pour les détails."},"headers":[],"relativePath":"fr/projects/grafik-visual-studio/calendar-plus.md","filePath":"fr/projects/grafik-visual-studio/calendar-plus.md","lastUpdated":1793447386000}'),i={name:"fr/projects/grafik-visual-studio/calendar-plus.md"};function o(l,e,u,d,c,p){return r(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="calendar" tabindex="-1">Calendar + <a class="header-anchor" href="#calendar" aria-label="Permalink to &quot;Calendar + {#calendar}&quot;">​</a></h1><p><strong>Calendar + 0.1.1</strong> est un ensemble de widgets externe, créé par <strong>rockbaer2007</strong> pour <strong>Grafik Visual Studio (version 0.1.267 ou ultérieure)</strong>. Il détecte automatiquement tous les calendriers disponibles dans Home Assistant et affiche les événements à venir sous forme de carte compacte ou de liste détaillée. Par défaut, tous les calendriers sont activés.</p><p>L&#39;environnement d&#39;exécution avec des données d&#39;exemple :</p><p><img src="'+t+'" alt="Calendar + avec des tuiles de calendrier colorées, des regroupements par jour et une liste d&#39;événements"></p><h2 id="originalprojekt" tabindex="-1">Projet original <a class="header-anchor" href="#originalprojekt" aria-label="Permalink to &quot;Projet original {#originalprojekt}&quot;">​</a></h2><p>Ce projet s&#39;inspire de <strong><a href="https://github.com/xBourner/calendar-card-plus" target="_blank" rel="noreferrer">calendar-card-plus de xBourner</a></strong>, publié sous <a href="https://github.com/xBourner/calendar-card-plus/blob/main/LICENSE" target="_blank" rel="noreferrer">licence MIT</a>, Copyright (c) 2026 xBourner. Calendar + utilise sa propre implémentation dans Studio ainsi qu&#39;une icône de palette dédiée. Le code source et les éléments graphiques originaux ne sont pas inclus. Cet ensemble est indépendant de « Industrial » et de la carte Lovelace originale (utilisable séparément).</p><h2 id="installieren" tabindex="-1">Installation <a class="header-anchor" href="#installieren" aria-label="Permalink to &quot;Installation {#installieren}&quot;">​</a></h2><ol><li>Mettre à jour Studio vers la version <strong>0.1.267 ou ultérieure</strong>.</li><li>Télécharger <a href="https://raw.githubusercontent.com/rockbaer2007/ugso-ha-mqtt-addons/master/ha_grafik_visual_studio/packages/calendar-plus/ugso.calendar-plus.wg" target="_blank" rel="noreferrer">ugso.calendar-plus.wg</a>.</li><li>Procéder à l&#39;installation via <strong>Paramètres → Packs de widgets → Local</strong>.</li><li>Faire glisser <strong>Calendar + → Kalender +</strong> depuis la palette vers la page.</li></ol><p>Le pack contient des données déclaratives, une icône, une documentation et la licence MIT. Le moteur de rendu hôte (<code>calendar-plus</code>) est fourni par Studio ; le pack ne contient aucun script exécutable. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/ha_grafik_visual_studio/packages/calendar-plus" target="_blank" rel="noreferrer">Code source et documentation du pack</a>.</p><h2 id="meine-kalender" tabindex="-1">Mes calendriers <a class="header-anchor" href="#meine-kalender" aria-label="Permalink to &quot;Mes calendriers {#meine-kalender}&quot;">​</a></h2><p>Toutes les entités <code>calendar.*</code> disponibles sont détectées, y compris les calendriers ne figurant pas dans le registre. Les entrées désactivées dans le registre de Home Assistant sont ignorées. Sous <strong>Mes calendriers</strong>, une section dédiée s&#39;affiche pour chaque calendrier, comprenant un identifiant d&#39;entité, une <strong>case à cocher en haut à droite</strong> (pour afficher ou masquer le calendrier), une <strong>couleur</strong> et, en option, une <strong>couleur d&#39;arrière-plan</strong>. Il n&#39;est pas nécessaire de saisir manuellement le nombre de calendriers.</p><p>À partir de la version Studio <strong>0.1.268</strong>, le groupe est désormais intitulé <strong>Paramètres des tuiles</strong> (auparavant « Couleurs »). L&#39;option <strong>Taille des tuiles du calendrier</strong> propose quatre tailles fixes : <strong>Très petite 36 × 44 px</strong>, <strong>Petite 44 × 52 px</strong>, <strong>Moyenne 58 × 64 px</strong> (par défaut) et <strong>Grande 76 × 82 px</strong>. Ce choix s&#39;applique à la liste des événements ainsi qu&#39;à la fenêtre contextuelle (pop-up) de détails. La taille du texte d&#39;en-tête est d&#39;au moins <strong>12 px</strong> et celle du chiffre du jour d&#39;au moins <strong>24 px</strong>, indépendamment de la taille de police globale. Même les widgets étroits conservent la taille sélectionnée. Les paquets existants (0.1.0/0.1.1) bénéficieront de ces paramètres lors de la mise à jour de Studio ; aucune réinstallation n&#39;est nécessaire. Le calendrier ne nécessite pas de configuration de flux de données ni de points d&#39;entrée/sortie.</p><p>La sélection et les couleurs sont conservées en fonction de l&#39;ID de l&#39;entité. Les calendriers nouvellement ajoutés sont affichés automatiquement ; les calendriers masqués ne font l&#39;objet d&#39;aucune interrogation concernant les événements. Le nombre de calendriers détectés n&#39;est pas limité. Les requêtes sont effectuées par groupes de 20 calendriers maximum via l&#39;interface Home Assistant.</p><h2 id="einstellungen" tabindex="-1">Paramètres <a class="header-anchor" href="#einstellungen" aria-label="Permalink to &quot;Paramètres {#einstellungen}&quot;">​</a></h2><p>À partir de la version Studio <strong>0.1.270</strong>, il est possible, via <strong>Paramètres des tuiles → Rayon des coins des tuiles (px)</strong>, de définir un rayon commun pour les quatre coins de la tuile de date : <strong>0 = angles droits</strong>, valeur par défaut <strong>10 px</strong>, maximum <strong>100 px</strong>. Ce paramètre s&#39;applique également à la fenêtre contextuelle (pop-up) de détails.</p><p>Le calendrier et l&#39;imprimante proposent désormais, sous <strong>Propriétés → WIDGET</strong>, toutes les sections CSS : <strong>CSS Général</strong>, <strong>CSS Police et texte</strong>, <strong>CSS Arrière-plan</strong>, <strong>CSS Bordures</strong> ainsi que <strong>CSS Ombres et espacements</strong>. Les quatre groupes supplémentaires sont désactivés par défaut afin de préserver l&#39;affichage actuel. Cochez la case correspondant au groupe souhaité, puis configurez la police, l&#39;arrière-plan/image, les bordures, le rayon, les ombres et les espacements. Ces paramètres définissent l&#39;apparence de la zone visible ; le rayon extérieur, situé sous <strong>CSS Bordures</strong>, est indépendant du rayon des petites cases de date. Les couleurs spécifiques — telles que celles des calendriers ou les états de l&#39;imprimante — conservent leurs propres paramètres de configuration. La section <strong>CSS Général</strong> reste active pour la gestion de la position, de la taille et de la visibilité. Aucun nouveau paquet n&#39;est requis.</p><p>À partir de la version Studio <strong>0.1.269</strong>, les <strong>paramètres des cases</strong> incluent désormais la <strong>taille de police en haut</strong> (mois/jour de la semaine, jusqu&#39;à 72 px) et la <strong>taille de police en bas</strong> (numéro du jour, jusqu&#39;à 120 px). La valeur <strong>0 = automatique</strong> applique les paramètres par défaut liés à la taille de case choisie. Il est possible de définir des valeurs personnalisées plus petites ; celles-ci seront automatiquement ajustées en cas d&#39;espace insuffisant. Les valeurs que vous avez enregistrées sont conservées, ce qui permet aux cases de plus grande taille d&#39;utiliser, le cas échéant, une police plus grande.</p><p>La zone d&#39;en-tête colorée s&#39;adapte à la taille de la police supérieure et à un certain espacement interne, tout en restant limitée à <strong>un tiers maximum de la hauteur de la tuile</strong>. Le numéro du jour est intégré dans l&#39;espace restant. La taille de la tuile demeure inchangée. Ces paramètres s&#39;appliquent à la liste des événements ainsi qu&#39;à la fenêtre contextuelle (pop-up) de détails et ne nécessitent pas de nouveau paquet de widgets.</p><table tabindex="0"><thead><tr><th>Zone</th><th>Paramètre</th></tr></thead><tbody><tr><td>Configuration</td><td>Libellé, aperçu sur <strong>1 à 90 jours</strong>, <strong>1 à 20</strong> événements visibles, déploiement des événements, fenêtre contextuelle de détails, séparateurs.</td></tr><tr><td>Regroupement</td><td>Par jour, avec possibilité de regrouper également par calendrier ; option pour afficher les jours vides.</td></tr><tr><td>Événements à venir</td><td>Affichage/masquage des indications temporelles relatives telles que « Demain », « Dans 2 jours » ou « En cours ».</td></tr><tr><td>Texte et visibilité</td><td>Activation/désactivation individuelle du nom du calendrier, de la date, du lieu, de la durée, de l&#39;heure et du jour de la semaine ; jour de la semaine en format complet ou abrégé ; inversion possible du mois et du jour de la semaine dans la tuile de date.</td></tr><tr><td>Paramètres des tuiles</td><td>Quatre tailles de tuiles, thème du navigateur (automatique ou fixe : clair/sombre), couleur d&#39;accentuation et taille de police (<strong>10 à 24 px</strong>). Couleurs de calendrier et arrière-plans configurables séparément pour chaque calendrier.</td></tr><tr><td>Taille</td><td>Taille par défaut <strong>480 × 460 px</strong>, taille minimale <strong>260 × 180 px</strong> ; en cas d&#39;espace restreint, la liste des événements devient défilante.</td></tr></tbody></table><p>Lorsque la liste n&#39;est pas déployée, un événement reste visible. Lors de l&#39;utilisation, un clic sur un événement ou sur « Tous les événements » ouvre la fenêtre contextuelle de détails, pouvant afficher jusqu&#39;à 100 événements. Celle-ci présente la date complète, le lieu et la description (si disponible). Les textes sont affichés en format texte brut. <strong>Fermer</strong>, la touche Échap ou un clic en dehors de la fenêtre permettent de fermer le popup.</p><h2 id="daten-und-aktualisierung" tabindex="-1">Données et mise à jour <a class="header-anchor" href="#daten-und-aktualisierung" aria-label="Permalink to &quot;Données et mise à jour {#daten-und-aktualisierung}&quot;">​</a></h2><p>L&#39;éditeur et le runtime récupèrent les événements via <code>calendar.get_events</code>. Pour les événements sur toute la journée, la date de fin est exclue ; les événements passés sont supprimés. La mise à jour automatique peut être désactivée sous <strong>Configuration → Mise à jour automatique (60 s)</strong> (activée par défaut). Lors de l&#39;ouverture d&#39;une page dans le runtime, le calendrier et les événements sont rechargés, même si la mise à jour automatique est désactivée. Le bouton <strong>↻</strong> permet une mise à jour manuelle ; la détection des calendriers est alors également actualisée.</p><p>Les mises à jour ne remplacent que les listes d&#39;événements ; elles préservent la position de défilement ainsi que l&#39;affichage d&#39;une fenêtre de détails ouverte. Les changements d&#39;état d&#39;autres widgets « live » n&#39;entraînent pas la reconstruction du calendrier (si celui-ci reste inchangé). La mise à jour s&#39;arrête lorsque l&#39;utilisateur quitte la page.</p><p>« Aucun calendrier trouvé », « Tous les calendriers masqués », « Aucun événement à venir » et une erreur de chargement correspondent à des états distincts. Une erreur n&#39;est pas affichée comme un calendrier vide. La langue s&#39;adapte automatiquement au paramètre <strong>DE/EN</strong> défini dans le Studio ; les libellés personnalisés et le contenu des événements restent inchangés.</p><h2 id="umfang-dieser-version" tabindex="-1">Contenu de cette version <a class="header-anchor" href="#umfang-dieser-version" aria-label="Permalink to &quot;Contenu de cette version {#umfang-dieser-version}&quot;">​</a></h2><p>Cette version permet de lire des événements (rendez-vous). Les fonctionnalités <strong>Nouvel événement</strong>, <strong>Modifier</strong> et <strong>Supprimer</strong> ne sont pas encore incluses. Les calendriers doivent être disponibles dans Home Assistant ; il n&#39;existe pas de connexion directe aux fichiers ICS ou à Google Agenda. Il n&#39;est pas nécessaire d&#39;installer la carte originale via HACS.</p>',26)])])}const v=s(i,[["render",o]]);export{f as __pageData,v as default};
